function exportReportCsv(){const rows=filteredFeeRows();if(!rows.length){toast('No report records to export.');return}const header=['Student Name','Father / Guardian','Phone','Class','Batch','Month','Amount','Status','Due Date','Payment Date','Payment Mode','Receipt No.'];const lines=[header.map(csvEscape).join(',')];rows.forEach(({f,s})=>lines.push([s.name,s.father,s.phone,s.className,s.batch,monthName(state.month),f.amount,f.status,dueDateForFee(f),(f.paymentDate||'').slice(0,10),f.paymentMode||'',f.receiptNo||''].map(csvEscape).join(',')));const blob=new Blob(['\ufeff'+lines.join('\n')],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`FEE-MANAGER-Fee-Report-${state.month}.csv`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('CSV report exported.')}
function printReport(){const rows=filteredFeeRows();if(!rows.length){toast('No report records to print.');return}const popup=window.open('', '_blank');if(!popup){toast('Please allow pop-ups to print the report.');return}const label=monthName(state.month);const total=rows.reduce((x,{f})=>x+Number(f.amount||0),0);const paid=rows.filter(({f})=>f.status==='Paid').reduce((x,{f})=>x+Number(f.amount||0),0);popup.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>FEE MANAGER Fee Report - ${escapeHtml(label)}</title><style>@page{size:A4;margin:16mm}body{font-family:Arial,sans-serif;color:#222}h1{margin:0 0 4px;font-size:24px}h2{margin:22px 0 8px;font-size:17px}p{margin:0 0 14px;color:#666}.summary{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:14px 0}.box{border:1px solid #ddd;border-radius:10px;padding:10px}.box b{display:block;font-size:18px;margin-top:4px}table{width:100%;border-collapse:collapse;font-size:11px}th,td{border:1px solid #ddd;padding:7px;text-align:left}th{background:#f4f3fb}.right{text-align:right}.paid{color:#187a4b;font-weight:700}.pending{color:#b33d43;font-weight:700}.foot{margin-top:18px;color:#777;font-size:10px}</style></head><body><h1>EZEE VISION</h1><p>Official Coaching Fee Report • ${escapeHtml(label)}</p><div class="summary"><div class="box">Total Fee<b>${escapeHtml(money(total))}</b></div><div class="box">Collected<b>${escapeHtml(money(paid))}</b></div><div class="box">Pending<b>${escapeHtml(money(Math.max(0,total-paid)))}</b></div></div><table><thead><tr><th>Student</th><th>Class</th><th>Batch</th><th>Status</th><th>Due Date</th><th class="right">Amount</th><th>Payment Date</th><th>Mode</th></tr></thead><tbody>${rows.map(({f,s})=>`<tr><td>${escapeHtml(s.name)}</td><td>${escapeHtml(s.className||'—')}</td><td>${escapeHtml(s.batch||'—')}</td><td class="${f.status==='Paid'?'paid':'pending'}">${escapeHtml(f.status)}${isOverdue(f)?' / OVERDUE':''}</td><td>${escapeHtml(dueDateForFee(f)||'—')}</td><td class="right">${escapeHtml(money(f.amount))}</td><td>${escapeHtml((f.paymentDate||'').slice(0,10)||'—')}</td><td>${escapeHtml(f.paymentMode||'—')}</td></tr>`).join('')}</tbody></table><div class="foot">Generated from FEE MANAGER. This report is computer generated.</div><script>window.onload=()=>window.print();</script></body></html>`);popup.document.close()}
async function saveSettings(patch){state.settings={...state.settings,...patch};await upsertUserProfile(state.uid,{settings:state.settings});render()}
function catalogData(type){return type==='classes'?state.settings.classes:type==='batches'?state.settings.batches:state.settings.subjects}
function openCatalogManager(type){const title=type==='classes'?'Classes':type==='batches'?'Batches':'Subjects';const items=catalogData(type);$('catalogModalTitle').textContent=title;$('catalogModalSubtitle').textContent=`Manage your ${title.toLowerCase()} in the cloud`;$('catalogType').value=type;$('catalogInput').value='';$('catalogList').innerHTML=items.map((x,i)=>`<div class="catalog-row"><span>${escapeHtml(x)}</span><button type="button" class="outline-btn mini" data-catalog-delete="${i}">DELETE</button></div>`).join('')||'<div class="muted-empty">No items yet.</div>';$('catalogModal').classList.add('show')}
function closeCatalog(){$('catalogModal').classList.remove('show')}
async function addCatalogItem(){const type=$('catalogType').value,value=$('catalogInput').value.trim();if(!value)return toast('Enter a name first.');const arr=[...catalogData(type)];if(arr.some(x=>x.toLowerCase()===value.toLowerCase()))return toast('Already exists.');arr.push(value);await saveSettings({[type]:arr});openCatalogManager(type);toast(`${value} added.`)}
async function deleteCatalogItem(index){const type=$('catalogType').value,arr=[...catalogData(type)],value=arr[index];if(!value)return;const inUse=type==='classes'?state.students.some(s=>s.className===value):type==='batches'?state.students.some(s=>s.batch===value):state.students.some(s=>(s.subjects||[]).includes(value));if(inUse)return toast(`Cannot delete ${value}; it is being used by a student.`);arr.splice(index,1);await saveSettings({[type]:arr});openCatalogManager(type);toast(`${value} deleted.`)}
