$('attendanceClassFilter').addEventListener('change',renderAttendance);$('attendanceBatchFilter').addEventListener('change',renderAttendance);$('attendanceList').addEventListener('click',e=>{const b=e.target.closest('[data-att]');if(!b)return;const id=b.dataset.att;const existing=state.attendance.find(x=>x.date===state.attendanceDate&&x.className===($('attendanceClassFilter').value||'All')&&x.batch===($('attendanceBatchFilter').value||'All'));const rec={...(existing?.records||{})};rec[id]=b.dataset.value;const holder={date:state.attendanceDate,className:$('attendanceClassFilter').value||'All',batch:$('attendanceBatchFilter').value||'All',records:rec};state.attendance=[...state.attendance.filter(x=>x.id!==existing?.id),holder];renderAttendance()});$('attendanceMarkAll').onclick=()=>{const students=attendanceFilteredStudents();const rec={};students.forEach(s=>rec[s.id]='Present');const existing=state.attendance.find(x=>x.date===state.attendanceDate&&x.className===($('attendanceClassFilter').value||'All')&&x.batch===($('attendanceBatchFilter').value||'All'));state.attendance=[...state.attendance.filter(x=>x.id!==existing?.id),{date:state.attendanceDate,className:$('attendanceClassFilter').value||'All',batch:$('attendanceBatchFilter').value||'All',records:rec,id:existing?.id}];renderAttendance()};$('saveAttendanceBtn').onclick=async()=>{try{const cls=$('attendanceClassFilter').value||'All',batch=$('attendanceBatchFilter').value||'All',existing=state.attendance.find(x=>x.date===state.attendanceDate&&x.className===cls&&x.batch===batch),rec=existing?.records||{};await saveAttendance(state.uid,{date:state.attendanceDate,className:cls,batch,records:rec});toast('Attendance saved successfully.')}catch(e){toast(cleanError(e))}};$('attendanceDateBtn').onclick=()=>{$('attendanceDateInput').value=state.attendanceDate;$('attendanceDateModal').classList.add('show')};$('attendanceDateCloseBtn').onclick=()=>$('attendanceDateModal').classList.remove('show');$('attendanceDateSaveBtn').o