function openInfoModal(type){const data={about:{title:'About FEE MANAGER',subtitle:'EZEE VISION CHAMPUA',html:`<div class="info-hero"><img src="assets/ezee-vision-logo.png" alt="EZEE VISION"><strong>FEE MANAGER</strong><span>Simple, cloud-connected coaching fee management.</span></div><div class="info-points"><div><b>Student Management</b><span>Keep student and fee records together.</span></div><div><b>Fees & Reports</b><span>Track collections, pending fees and receipts.</span></div><div><b>Attendance & Expenses</b><span>Manage day-to-day coaching records in one place.</span></div></div>`},privacy:{title:'Privacy Policy',subtitle:'Your data & privacy',html:`<div class="policy-copy"><p><strong>FEE MANAGER</strong> stores the coaching records you enter in your connected cloud account so they can be available to you on signed-in devices.</p><h3>What we store</h3><p>Account information, student details, fee records, attendance, expenses and settings entered through the app.</p><h3>Access</h3><p>Your records are protected by your signed-in account and the application's database security rules.</p><h3>Your control</h3><p>You can edit or delete records from the app. Keep your account password private and use trusted devices.</p></div>`},terms:{title:'Terms & Conditions',subtitle:'Using FEE MANAGER',html:`<div class="policy-copy"><p>By using <strong>FEE MANAGER</strong>, you agree to use the app for lawful coaching or tuition management.</p><h3>Account responsibility</h3><p>You are responsible for the credentials used to access your account and data.</p><h3>Records</h3><p>Check student details, amounts and payment status before issuing receipts or sharing payment messages.</p><h3>Third-party services</h3><p>Cloud, browser and messaging services can have their own availability and terms.</p></div>`},rate:{title:'Rate FEE MANAGER',subtitle:'We value your feedback',html:`<div class="rate-card"><div class="rate-stars" id="rateStars"><button type="button" data-rate="1">★</button><button type="button" data-rate="2">★</button><button type="button" data-rate="3">★</button><button type="button" data-rate="4">★</button><button type="button" data-rate="5">★</button></div><p id="rateMessage">Tap the stars to rate your experience.</p><div class="info-note">Play Store rating can be connected after the Android app is published.</div></div>`}}[type];if(!data)return;$('infoTitle').textContent=data.title;$('infoSubtitle').textContent=data.subtitle;$('infoContent').innerHTML=data.html;$('infoActions').innerHTML='<button class="outline-btn" id="infoDoneBtn" type="button"><span class="btn-icon-3d">✓</span><span>DONE</span></button>';$('infoModal').classList.add('show');$('infoModal').setAttribute('aria-hidden','false');$('infoDoneBtn').onclick=closeInfoModal;document.querySelectorAll('#rateStars [data-rate]').forEach(btn=>btn.addEventListener('click',()=>{const n=Number(btn.dataset.rate);document.querySelectorAll('#rateStars [data-rate]').forEach((b,i)=>b.classList.toggle('selected',i<n));$('rateMessage').textContent=`Thanks for rating FEE MANAGER ${n}/5.`;}))}
