$('attendanceReportBtn').onclick=openAttendanceReport;$('attendanceReportCloseBtn').onclick=closeAttendanceReport;$('attendanceReportMonth').addEventListener('change',renderAttendanceReport);$('attendanceReportClass').addEventListener('change',renderAttendanceReport);$('attendanceReportBatch').addEventListener('change',renderAttendanceReport);$('attendanceReportExportBtn').onclick=exportAttendanceCsv;$('attendanceReportPrintBtn').onclick=printAttendanceReport;
$('profileModal').addEventListener('click',e=>{if(e.target===$('profileModal'))closeStudentProfile()});$('idCardModal').addEventListener('click',e=>{if(e.target===$('idCardModal'))closeIdCard()});$('attendanceReportModal').addEventListener('click',e=>{if(e.target===$('attendanceReportModal'))closeAttendanceReport()});
window.mmtAction=async(type,id)=>{if(type==='profile'){openStudentProfile(id);return}if(type==='idcard'){openIdCard(id);return}if(type==='wa'||type==='call'){const s=state.students.find(x=>x.id===id);if(!s?.phone){toast('Phone number not available.');return}if(type==='call')location.href='tel:'+s.phone.replace(/[^\d+]/g,'');else window.open('https://wa.me/'+normalizedPhone(s.phone),'_blank');return}if(type==='edit'){openStudentModal(id);return}const f=state.fees.find(x=>x.id===id);if(!f)return;if(type==='paid'){openPaymentModal(id);return}if(type==='revert'){if(await appConfirm('Revert this payment to Pending?',{title:'Revert Payment',confirmText:'OK'}))try{await updateFee(state.uid,id,{status:'Pending',paymentDate:null,receiptNo:null,paymentMode:null,paymentNote:null,paidAmount:null});toast('Payment reverted.')}catch(e){toast(cleanError(e))}return}if(type==='remind'){const s=state.students.find(x=>x.id===f.studentId);if(!s?.phone){toast('Phone number not available.');return}const text=`Dear ${s.father||'Parent'},\n\nThis is a reminder regarding the coaching fee of ${s.name} for ${monthName(f.month||state.month)}.\nPending Amount: ${money(f.amount)}\nDue Date: ${dueDateForFee(f)||'-'}\n\nThank you.\nEZEE VISION`;window.open('https://wa.me/91'+s.phone.replace(/\D/g,'')+'?text='+encodeURIComponent(text),'_blank');return}if(type==='sendReceipt'){shareReceiptToWhatsApp(id);return}if(type==='receipt')openReceipt(id)};
document.querySelectorAll('[data-action]').forEach(btn=>btn.addEventListener('click',async()=>{const a=btn.dataset.action;closeDrawer();$('profileMenu').classList.remove('show');if(a==='logout'){await signOut(auth);return}if(a==='profile'){openCoachProfile();return}if(a==='classes'||a==='batches'||a==='subjects'){openCatalogManager(a);return}if(a==='fee-settings'){openFeeSettings();return}if(a==='attendance-report'){nav('attendance');setTimeout(openAttendanceReport,0);return}if(a==='rate'||a==='about'||a==='privacy'||a==='terms'){openInfoModal(a);return}}));
async function loadSettings(user){try{const profile=await getUserProfile(user.uid);const saved=profile?.settings||{};state.settings={classes:Array.isArray(saved.classes)&&saved.classes.length?saved.classes:DEFAULT_SETTINGS.classes,batches:Array.isArray(saved.batches)&&saved.batches.length?saved.batches:DEFAULT_SETTINGS.batches,subjects:Array.isArray(saved.subjects)&&saved.subjects.length?saved.subjects:DEFAULT_SETTINGS.subjects,dueDay:Math.min(28,Math.max(1,Number(saved.dueDay||DEFAULT_SETTINGS.dueDay)))};}catch(_){state.settings={...DEFAULT_SETTINGS}}}
async function setSignedIn(user){state.uid=user.uid;state.user=user;document.body.classList.add('app-ready');$('authScreen').hidden=true;$('app').hidden=false;await loadSettings(user);render();state.unsub=[subscribeStudents(user.uid,d=>{state.students=d;render()},e=>toast(cleanError(e))),subscribeFees(user.uid,d=>{state.fees=d;render()},e=>toast(cleanError(e))),subscribeAttendance(user.uid,d=>{state.attendance=d;render()},e=>toast(cleanError(e))),subscribeExpenses(user.uid,d=>{state.expenses=d;render()},e=>toast(cleanError(e)))];upsertUserProfile(user.uid,{displayName:user.displayName||user.email?.split('@')[0]||'Coach',email:user.email||'',app:'FEE MANAGER',settings:state.settings}).catch(()=>{})}
function setSignedOut(){state.unsub.forEach(u=>u?.());state.unsub=[];state.uid=null;state.user=null;state.students=[];state.fees=[];state.attendance=[];state.expenses=[];state.settings={...DEFAULT_SETTINGS};document.body.classList.remove('app-ready');$('authScreen').hidden=false;$('app').hidden=true}
let signup=false;function updateAuthMode(){$('authTitle').textContent=signup?'Create your account':'Welcome back';$('authSubtitle').textContent=signup?'Start managing your coaching fees in the cloud':'Sign in to your coaching fees manager';$('authName').hidden=!signup;$('authName').required=signup;$('authPassword').autocomplete=signup?'new-password':'current-password';$('authSubmit').textContent=signup?'CREATE ACCOUNT':'SIGN IN';$('authSwitch').textContent=signup?'I already have an account':'Create a new account'}
$('authSwitch').onclick=()=>{signup=!signup;setAuthStatus('');updateAuthMode()};function setAuthStatus(msg=''){$('authStatus').textContent=msg}
$('authForm').addEventListener('submit',async e=>{e.preventDefault();setAuthStatus('');if(!firebaseConfigured){$('authSetup').hidden=false;setAuthStatus('Connect Firebase first.');return}const email=$('authEmail').value.trim(),password=$('authPassword').value;try{if(signup){const cred=await createUserWithEmailAndPassword(auth,email,password);const name=$('authName').value.trim();if(name)await updateProfile(cred.user,{displayName:name});await upsertUserProfile(cred.user.uid,{displayName:name||email.split('@')[0],email,app:'FEE MANAGER',settings:DEFAULT_SETTINGS});toast('Account created.')}else await signInWithEmailAndPassword(auth,email,password)}catch(err){setAuthStatus(cleanError(err))}});
if(!firebaseConfigured){$('authSetup').hidden=false;$('authForm').querySelectorAll('input,button').forEach(el=>{if(el.id!=='authSwitch')el.disabled=true})}
updateAuthMode();
if(auth)onAuthStateChanged(auth,u=>u?setSignedIn(u):setSignedOut());
